import json
s=[('cobalt',[0,1,2,3,4],1320,360),('reed',[0,2,4],1380,180),('plum',[1,3,5],30,150),('shell',[6],1350,90),('gold',[0],0,90),('elm',[5],60,180)]
def receiver(d,m,fault=None):
    hits=[]
    for i,(r,days,a,b) in enumerate(s):
        duration=(b-a)%1440
        if a<b:
            covers=d in days and a<=m<b
        elif fault=='day_owner':
            covers=d in days and (m>=a or m<b)
        else:
            covers=(d in days and m>=a) or ((d-1)%7 in days and m<b)
        if covers: hits.append((duration,i,r))
    if not hits:return 'idle'
    if fault=='first_match':return min(hits,key=lambda x:x[1])[2]
    return min(hits)[2]
jobs=[(1,29),(1,30),(1,150),(1,179),(1,180),(5,59),(5,60),(5,149),(5,150),(5,180),(6,1349),(6,1350),(0,0),(0,89),(0,90),(2,359),(2,360),(4,1380)]
w={}
for fault,other in [('day_owner','first_match'),('first_match','day_owner')]:
    for d in range(7):
        for m in range(1440):
            correct=receiver(d,m)
            if receiver(d,m,fault)!=correct and receiver(d,m,other)==correct:
                w[fault]={'job':{'receiver':{'day':d,'minute':m}},'expected':correct}
                break
        if fault in w:break
    assert fault in w
out={'routes':[receiver(d,m) for d,m in jobs],'witnesses':w}
assert set(out)=={'routes','witnesses'}
assert len(out['routes'])==18
for fault,other in [('day_owner','first_match'),('first_match','day_owner')]:
    v=w[fault];d=v['job']['receiver']['day'];m=v['job']['receiver']['minute']
    assert 0<=d<=6 and 0<=m<=1439
    assert receiver(d,m)==v['expected'] and receiver(d,m,fault)!=v['expected'] and receiver(d,m,other)==v['expected']
print(json.dumps(out,separators=(',',':')))

